insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit numerals up to 1000,000', 'B5.1.1.1.1', 'Model number quantities up to 1,000,000 using graph sheets and multi-base block', 'E.g.; 1. Ask pupils to model number quantities up to 1000,000 using graph sheets or multi-base materials. For instance, with multi-base block, a cube = 1000 unit; a rod = 10,000; a flat = 100,000 and a block = 1,000,000; learners model 436,000 with the appropriate materials E.g.; 2. Ask pupils to model the number 137,000 shading graph sheet square as shown below, where 1cm×1cm square represents 1000 units .', 10),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit numerals up to 1000,000', 'B5.1.1.1.2', 'Read and write numbers in figures and in words up to 1000,000', 'E.g. 1 Play the place value number wheel game: Use the million number wheel to generate 7-digit numbers and represent the number generated on a place value frame. Throw a number of pebbles (or stones) onto the number wheel, identify the number of pebbles landing in each place value ring, and state the number generated in the wheel (i.e. 2 landed in the ten-thousands’ ring making the number twenty- thousand or 20,000) E.g.; 2. Ask pupils to write given numbers on the expanded form of the number : 2,524,513=1000,000× 2 +100,000× 5 + 10,000 × 2+1000 × 4+ 100× 5 + 10× 1+ 1× 3 = 2,000,000 + 500,000 + 20,000 + 4,000 + 500 + 10 + 3', 20),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit numerals up to 1000,000', 'B5.1.1.1.3', 'Identify numbers in different positions around a given number in a number chart', 'E.g. 1 Display a number chart in multiples of 1,500 between 10,000 and 1000,000 and lead learners identify numbers in different positions around a given number. Put learners in pairs and give each group a number grid and have them identify numbers in different positions around a chosen number 10,000 11,500 12,000 13,500 15,000 16,500 20,000 21,500 22,000 23,500 24,000 25,500 30,000 31,500 33,000 34,500 36,000 37,500 40,000 41,500 43,000 44,500 46,000 47,500 50,000 51,500 53,000 54,500 56,000 57,500 60,000 61,500 63,000 64,500 66,000 67,500', 30),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit numerals up to 1000,000', 'B5.1.1.1.4', 'Compare and order whole numbers up to 100,000 and represent the comparison using ">, <, or ="', 'E.g. 1 Learners identify numbers which are 10,000 more or 10,000 less than a given six-digit number. E.g. 122,400 is 1,000 less than133,400 Learners use words such as: “equal to” “greater than” “less than” and later use symbols such as “<”, “=”, “>” to compare numbers up to 10,000 taking into consideration the place value of each digit in the given number. E.g. 251200 = 251,200; 132,734 > 132,635 E.g. 2 Learners work together in their groups to order a given set of numbers in ascending or descending order verbally and in writing. E.g. 1020,1025, 2673,2873,', 40),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit numerals up to 1000,000', 'B5.1.1.1.5', 'Round (off, up, down) whole numbers up to 100,000 to the nearest ten thousands, thousands, hundreds and tens', 'E.g. 1 Learners round off numbers to the nearest 10,000, 1000 and 100. For instance; 129,500 is approximately 130,000 and 19100 as approximately 19,000 E.g. 2 Learners round up and round down to estimate sums and differences NB: To round down learners consider the smaller of the two approximated numbers, while round up considers the bigger of the two numbers. The table below may bring the meaning of these two concepts clearer 214765 Round up Round down Round off to the nearest ten 214770 214760 214770 to the nearest hundred 214800 214700 214800 to the nearest thousand 215000 214000 215000', 50),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit numerals up to 1000,000', 'B5.1.1.1.6', 'Skip count forwards and backwards in 500s 1000s etc. up to and from 100,000', 'E.g. 1 Put learners into convenient groups. A learner mention a number and another makes skip count in 500s or 1000s to include the fifth count. For instance. Learner 1: Shout out “15290”skip counting up in 500s Learner 2: 15790, 16290, 17290, 17790, 18290, etc. Learner 3; Shout out “31285”skip counting up in 1000s Learner 4; 32285, 33285, 34285, 35285, 36285….etc. E.g. 2 Skip count forwards and backwards by 50s and between 1000 and 10000 that are multiples of 50s and 100s but make an error or leave out a number. Challenge learners to identify or correct error.', 60),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.2', 'Demonstrate understanding of Roman Numerals up to C (i.e. 100)', 'B5.1.1.2.1', 'Recognize Roman Numerals system up to C (i.e. 100)', 'E.g. 1 Display roman numeral charts (1-100) arranged in sequential order and lead learners to identify the numerals. Learners identify the main characters of the roman numerals used to build the table up to 30 i.e. I, II, III, IV, V, X, L and C Call out a numeral and have learners point at it from the chart E.g. 2 Have learners match the Roman numerals to the Hindu-Arabic numerals for instance I = 1; V= 5: IX= 9, XV= 15, XXX = 30, XL = 40, LVI = 56, XCIX =; 99. Mention some numerals randomly and have learners point at it on the chart.', 70),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.2', 'Demonstrate understanding of Roman Numerals up to C (i.e. 100)', 'B5.1.1.2.2', 'Count and convert Hindu Arabic numbers to Roman numerals up to 100 (C) and vice versa', 'E.g. 1 Learners read the chart sequentially forwards and backwards, vertically (up and down), zig-zag, diagonally and randomly without pointing to the numbers. Invite 2-3 learners to read to the class. Call a Roman numeral and ask learners to write E.g. 2 Give learners a numeral in the Hindu Arabic system and have learners convert to roman numeration and vice versa for instance XXIV = 24, LX = 60, XCIV = 94, ETC.', 80),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.3', 'Demonstrate an understanding of factors, multiples of numbers including composite, even, odd and prime numbers from 1 to 100', 'B5.1.1.3.1', 'Identify the factors of whole numbers 1 - 100', 'E.g. 1 Ask learners to use different arrangements of arrays of objects to find factors of whole numbers 1 – 100. For instance the factors of 24 can be obtained from the following arrays of objects. E.g. 2 Ask learner to collect from the arrays, pairs of number as the factors of the given number,; 24. Hence the set of factors of 24 = {1,2,3,4,6,8,12,24}', 90),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.3', 'Demonstrate an understanding of factors, multiples of numbers including composite, even, odd and prime numbers from 1 to 100', 'B5.1.1.3.2', 'Generate and identify prime numbers and composite numbers between 1 and 100', 'E.g. 1 Ask learners to use different arrangements of arrays of objects (or the factorization method)to find factors of the first 30 whole numbers and use their results to complete the table below. Have learners identify prime numbers; i.e. number with only two factors, 1 and the number itself; other are composite. Number of Numbers Factors factors 1 1 1 2 1, 2 2 3 1, 3 2 4 1, 2, 4 3 5 1, 5 2 ∙ ∙ ∙ 30 1,2, 3, 5, 6, 10, 15, 30 E.g. 2 In convenient groups, have learners use the “Sieve of Eratosthenes” to identify prime numbers between 1 and 100, i.e. dividing through by whole numbers starting from 2; numbers that cannot be divided by other numbers except the number itself are prime numbers.; Factors; 1; 1, 2; 1, 3; 1, 2, 4; 1, 5; 1,2, 3, 5, 6, 10, 15, 30', 100),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.3', 'Demonstrate an understanding of factors, multiples of numbers including composite, even, odd and prime numbers from 1 to 100', 'B5.1.1.3.3', 'Identify even and odd numbers between 1 and 100 as number that can be arrayed in twos array and those which cannot', 'E.g. 1 Ask learners to use arrangements of twos arrays of objects to find even and odd numbers between 1 and 100 E.g. 2 Ask learner to collect from the arrays, pairs to skip count in twos starting from 1 to generate odd numbers, and skip count in twos starting from 2 to generate even numbers', 110),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.3', 'Demonstrate an understanding of factors, multiples of numbers including composite, even, odd and prime numbers from 1 to 100', 'B5.1.1.3.4', 'Determine the highest common factor of any 2 or 3 numbers by prime factorisation', 'E.g.; 1. Have learners use factor tree method to determine prime factors of any given whole number. For example the prime factors of 24 For instance, from the figure 24 = 2×2×2×3 so 2 and 3 are the prime factors of; 24. Ask learners to list the factors of two or more given whole numbers using the factor tree; for 36 and 48 we have 36= 2×3×2×3 =2×2×3×3 and 48= 2×3×2×2×2 = 2×2×2×2×3. E.g. 2 Learners use the prime factorization to determine the HCF by underlining the common factors in each product 36=2×2×3×3 48= 2×2×2×2×3 → which is 2×2×3=12; E.g. 3 Learners use the prime factorization by inspection to determine the LCM by underlining the largest number of factors in each product 36=2×2×3×3 48= 2×2×2×2×3 → which is 2×2×2×2×3×3=144', 120),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.1.3', 'Demonstrate an understanding of factors, multiples of numbers including composite, even, odd and prime numbers from 1 to 100', 'B5.1.1.3.5', 'Recognize relationship between factors and multiples of whole numbers from 1 to 100', 'E.g. 1 Investigate even and odd numbers. How do you know a number is even or odd? E.g. 2 Investigate numbers that are multiples of 4 and; 6. How do you know a number is a multiple of 4? a multiple of 6? (This is also known as the divisibility test). E.g. 3 Investigate perfect numbers, that is, numbers whose factors add up to the number; for instance 6 has factors 1, 2, 3 and; 6. The sum of factors other than 6 is 1+2+3 =6, and hence 6 is a perfect number. How many more perfect number can we find in the first 100 whole numbers?', 130),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.1', 'Describe and apply mental mathematics strategies and number properties to determine answers for basic multiplication facts to 81 and related division facts', 'B5.1.2.1.1', 'Apply mental mathematics strategies and number properties, such as skip counting from a known fact, using doubling or halving, using patterns in the 9sfacts, using repeated doubling or halving, to determine answers for basic multiplication facts to 81 and related division facts', 'E.g. 1 Describe the mental mathematics strategies used to determine a given basic fact, such as  skip count up by one or two groups from a known fact (e.g., if 5 × 7 = 35, then 6 × 7 is equal to 35 + 7 and 7 × 7 is equal to 35 + 7 +; 7)  skip count down by one or two groups from a known fact (e.g., if 8 × 8 = 64, then 7 × 8 is equal to 64 – 8 and 6 × 8 is equal to 64 – 8 –; 8)  doubling (e.g., for 8 × 3 think 4 × 3 = 12, and 8 × 3 = 12 +; 12)  patterns when multiplying by 9 (e.g., for 9 × 6, think 10 × 6 = 60, and 60 – 6 = 54; for 7 × 9, think 7 × 10 = 70, and 70 – 7 =; 63)  repeated doubling (e.g., if 2 × 6 is equal to 12, then 4 × 6 is equal to 24 and 8 × 6 is equal to; 48)  repeated halving (e.g., for 60 ÷ 4, think 60 ÷ 2 = 30 and 30 ÷ 2 =; 15)  relating division to multiplication (e.g., for 64 ÷ 8, think 8 × … =; 64) E.g. 2 Recall multiplication facts to 81and related division facts', 140),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.1', 'Describe and apply mental mathematics strategies and number properties to determine answers for basic multiplication facts to 81 and related division facts', 'B5.1.2.1.2', 'Apply mental mathematics strategies for multiplication, such as annexing then adding zero halving and doubling using the distributive property', 'E.g. 1 Determine the products when one factor is a multiple of 10, 100, or 1000 by annexing zero or adding zeros (e.g., for 3×200 think of 3×2 and then add two zeros) E.g. 2 Apply halving and doubling when determining a given product (e.g., 32×5 is the same as 16×10) E.g. 3 Apply the distributive property to determine a given product involving multiplying factors that can be written in the expanded form (e.g., 6×18 = (6×10) + (6×8) = 60+48 = 108. Or apply distributive property to determine a given product involving multiplying factors that are close to multiples of 10 (e.g., 29×7 = (30×7) – (1×7) = 203. E.g. 4 Explain the property for determining the answer when multiplying numbers by i. one ii. zero.', 150),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.2', 'Demonstrate an understanding of multiplication of a 2 or 3-digit number by a 2 or 3-digit number', 'B5.1.2.2.1', 'Multiply multi digit numbers by 2-digit numbers efficiently', 'E.g.; 1. Multiplication of whole numbers using the “expand and box” method (partial decomposition method). Lead learners to multiply a 3-digit number by a 1-digit number as shown below, for example 448 ×2 =? × 400 40 8 2 800 80 16 448 ×2 = (400×2)+(40×2)+(8×2) = 800+80+16 = 800+80+(10+6) = 800+90+6 = 896 E.g.; 2. Multiplication of whole numbers using the Column or vertical method; i.e. 25×32 E.g.; 3. Multiplication of whole numbers using the Distributive property; i.e. 25×32', 160),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.3', 'Recall basic division fact up to 100', 'B5.1.2.3.1', 'Determine basic division fact up to 81', 'E.g.; 1. Investigate numbers that are multiples of 3,4, 6, 8 and; 9. How do you know a number is divisible by 3, 4, 6, 9? (This is also known as the divisibility test). E.g.; 2. Draw a 6 by 6 multiplication chart and use it as a game board to play the 3-in-a-line game with a pair of dice or playing cards. Players take turns in throwing a one dice and mark (or cover) a number that can be divided by the results (i.e. a quotient). The winner is the one who obtains three numbers in a line.', 170),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.4', 'Demonstrate an understanding of division of a 2 or 3- digit number by a 1 or 2-digit number', 'B5.1.2.4.1', 'Divide 3-digit numbers by 1-digit number efficiently', 'E.g.; 1. Division as repeated subtraction (using the long division method). Explain division as a way of repeatedly subtracting a divisor number from a given dividend until there is none left and then determining the number of times the divisor is taken from the dividend', 180),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.5', 'Translate word problems into mathematical sentences and solve', 'B5.1.2.5.1', 'Solve multi step word problems involving the four basic operations', 'E.g.; 1. Learners model mathematical statements from a given word problem involving addition and multiplication and solve using the strategies learnt E.g.; 2. Learners model mathematical statements from a given word problem involving division and subtraction and solve using the strategies learnt E.g.; 3. Learners role play a given word problem involving addition and multiplication and solve E.g.; 4. Learners role play a given word problem involving subtraction and division and solve E.g.; 5. Learners model mathematical statements from a given word problem involving division and multiplication and solve using the strategies learnt. The relationship between operations and the use of calculator and spreadsheet to assess the reasonableness of answers should be stressed.', 190),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B5.1.2.6', 'Demonstrate understanding of integers', 'B5.1.2.6.1', 'Solve simple addition and subtraction problems involving integers', 'E.g.; 1. Use number line to help learners to do the following types (addition) (1) 9 + -4 = _____ (2) -8 + 4 = _____ (3) -3 + -5 = _____ (4) 1 + -3 = _____ (5) -6 + 5 = _____ (6) 6 + -2 = _____ (7) -6 + 8 = _____ (8) -2 + 9 = ______ E.g. 2 Use number line to help learners to do the following types (subtraction) (9) -5 – 1 = ____ (10) -2 – 1 = ____ (11) 8 – 7= ____ (12) 2 – 6 = _____ (13) -1 – 7 = ____ (14) -5 – 7= ____ (15) -8 – 8= ____ (16) 4 – 6 = _____ E.g.; 3. Solve word problems; e.g. (i) Some number added to 5 is equal to -11. Find the number. (ii) Ben and Cam are diving. Ben is 15.8 meters below the surface of the water. Cam is 4.2 meters above Ben What is Cam''s position relative to the surface of the water?', 200),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.3.1', 'Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions B5.1.3.1 Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions', 'B5.1.3.1.1', 'Determine equivalent fractions of given fractions 3 5 7', 'E.g. 1 To compare, add or subtract the fractions, , and , we need find the Lowest Common 46 10 Denominator (LCD) and use this to express the equivalent fractions. Use the prime factorising strategy to determine the LCD of 4, 6, and; 20. Use the LCD work out the equivalent fractions. 3 ? 5 ?? 7 ??? = ; = ; and = . 4 36 6 36 10 36 [To obtain the numerators, determine how many times the denominator goes into the LCD and multiply this by the numerator to obtain a new numerator.] 24 = 2 x 2 x 2 x 3 so 2 and 3 are prime factors of 24', 210),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.3.1', 'Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions B5.1.3.1 Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions', 'B5.1.3.1.2', 'Compare and order fractions', 'E.g. 1 Find the Lowest Common Denominator (LCD) of the fractions and use this to express their 5 3 2 equivalent fractions and use them for the comparison; e.g. which is larger, and or ? 6 4 3 E.g. 2 Change the fractions to percentages or decimals and use them for the comparison. 5 3 2 i.e. = 0.83, = 0.75, and = 0.66, and compare. 6 4 3', 220),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.3.1', 'Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions B5.1.3.1 Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions', 'B5.1.3.1.3', 'Use the concept of equivalent fractions in changing fractions to the same denominator for addition and subtraction of like fractions (one denominator being a multiple of the other) 1 2', 'E.g. 1 To add or subtract the fractions, and , we need find the Lowest Common Denominator (LCD) 3 6 2 and use this to express the equivalent fractions. The LCD is 6 and the equivalent fractions are 6 2 2 2 2+2 4 2 and ; their sum is + is , which is, = = (i.e. its simplest form) 6 6 6 6 6 3 2 2 E.g. 2 To add or subtract the fractions, and , we need find the Lowest Common Denominator (LCD) 3 5 10 and use this to express the equivalent fractions. The LCD is 15 and the equivalent fractions are 15 6 10 6 10 − 6 4 − and ; their difference is = = 15 15 15 15 15', 230),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.3.1', 'Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions B5.1.3.1 Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions', 'B5.1.3.1.4', 'Use the concept of equivalent fractions for addition and subtraction of fractions greater than one (improper or mixed fractions) 1 2', 'E.g. 1 To add like mixed fractions that are larger than 1, i.e. 2 and 3 , we write down the sum of the 3 3 1 2 1 2 1+2 3 , whole numbers and add the fractions; i.e. 2 + 3 = 5 + + = 5 = 5 =; 6. 3 3 3 3 3 3 1 2 E.g. 2 To subtract like-fractions that are larger than 1, i.e. 2 and 3 , we change the mixed fractions into 3 3 improper fractions and subtract; i.e. 3 2 − 2 1 + = 11 − 7 + = 11−7 = 4 . = 1 1 3 3 3 3 3 3 3 1 2 E.g. 3 To add or subtract improper fractions with different denominators, (2 and 3 ) we need find the 3 5 Lowest Common Denominator (LCD) and use this to express the equivalent fractions. The LCD is 15 and 5 6 1 2 5 6 5+6 the equivalent fractions are 2 and 3 ; their sum is 2 + 3 = 2 + 3 = 5 15 15 3 5 15 15 15', 240),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.3.1', 'Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions B5.1.3.1 Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions', 'B5.1.3.1.5', 'Use models to explain the result of multiplying a whole number by a fraction 2', 'E.g. 1 Multiplying a whole number by a fraction, e.g. 5 × 3 2 2 2 2 or finding five two-thirds means + + + + 3 3 3 3 2 10 1 = = 3 3 3 3 E.g. 2 To multiply a whole number by a mixed fraction (e.g. 3 2 × 2 ) one can multiply the whole number by the 3 whole number and then whole number by the fraction and add the products or change the mixed fraction to improper fraction and multiply; 2 2 2 2 2 6 i.e. 3 × 2 = (3×2) + 3× ) = 6 + + + = 6 = 8 or 3 3 3 3 3 3 2 2 2 2 2+2+2 6 3 × 2 = 2 + 2 + 2 = 6 = 6 = 8 3 3 3 3 3 3 2 E.g. 3 To multiply a whole number by a fraction (e.g. 3 × 2 ) first change all into common fractions, then 3 multiply the numerators separately and multiply the denominators separately and simplify; 2 3 8 3×8 24 i.e. 3 × 2 = × = = = 8 3 1 3 1×3 3', 250),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.3.1', 'Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions B5.1.3.1 Demonstrate understanding of strategies for comparing, adding, subtracting and multiplying fractions', 'B5.1.3.1.6', 'Use models to explain the result of multiplying a fraction by whole number', 'E.g. 1 Multiplying a fraction by a whole number the', 260),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.4.1', 'Demonstrate understanding of decimals fractions and strategies for comparing, adding and subtracting decimal fraction', 'B5.1.4.1.1', 'Describe and represent decimals (up to the thousandths) concretely, pictorially, and symbolically and relate them to fractions', 'E.g. 1 Use several pictorial representations or number line to introduce tenths and thousandths and ask pupils to identify the fractions (i.e. A, B, C, D, E, & F) E.g. 2 Use the tenth to thousandth place value chart to illustrate how to write the fraction as a base ten number with the introduction of the decimal point “∙” after ones place in the place value chart', 270),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.4.1', 'Demonstrate understanding of decimals fractions and strategies for comparing, adding and subtracting decimal fraction', 'B5.1.4.1.2', 'Compare and order decimal fractions and a mixture of common and decimal fractions (up to the thousandths) using the symbols <, >, or =', 'E.g. 1 To compare and order a mixture of common, decimal and percent fractions, express 5 them in one form (i.e. either common, decimal or percent); e.g. to order 0.758, 8 5 625 758 73 and 73%; we have → = = 62.5%, 0.758 = = 75.8%, and 73% = 8 1000 1000 100 5 = 0.73, Hence the order from least to the largest is , 73% and 0.758 8 E.g. 2 To compare and order a mixture of common, decimal and percent fractions you can locate the fractions on the number and order them', 280),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.4.1', 'Demonstrate understanding of decimals fractions and strategies for comparing, adding and subtracting decimal fraction', 'B5.1.4.1.3', 'Round decimals to the nearest tenth and hundredth', 'E.g. 1 Explain the rule for of rounding decimals, which is similar to that of rounding whole numbers. That is, rounding to the nearest tenth means that the rounded figure has one digit after the decimal mark. Rounding to the nearest hundredth means that the rounded figure has two digits after the decimal mark E.g. 2 Use a table with several decimals fractions and explain Round to the rule for of rounding decimals. Give pupils a table Fractio Neares of decimal fractions to round to the nearest tenths n t Result or hundredths. 1 A 0.38 0.4 10 1 E.g. 3 Ask students to change fractions to decimal writing B 4.085 their results to the nearest tenths or hundredths. 10 1 C 56.584 10 1 D 18.096 100 1 E 30.084 100', 290),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.4.1', 'Demonstrate understanding of decimals fractions and strategies for comparing, adding and subtracting decimal fraction', 'B5.1.4.1.4', 'Use models to explain the result of addition and subtraction of decimals (up to the thousandths) 645 39 645+390 1035', 'E.g. 1 To add 0.645 and 0.39, means sum + which is = = 1.035. That is, since 1000 100 1000 1000 one is hundredths and other thousandths (i.e. one has 2 decimal places and the other 3 decimal places) we can line up the decimal points to align the place values and add as whole numbers E.g. 2 To subtract 0.395 from 0.6 and, one number is in tenths and other is in thousandths (i.e. one has 1 decimal place and the other 3 decimal places) it is important to line up the decimal points to align the place values and add as whole numbers.', 300),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.4.1', 'Demonstrate understanding of decimals fractions and strategies for comparing, adding and subtracting decimal fraction', 'B5.1.4.1.5', 'Use models to explain the result of multiplying a decimal (up to the thousandths) by a whole number 2 1', 'E.g. 1 Review multiplying a fraction by a whole number. e.g. ×10 means shade 2×( 𝑜𝑓; 10) ; i.e. 5 5 2×(2) = 4; E.g. 2 To multiply a decimal fraction by a whole number, change the decimal number to common fraction 4 and multiply e.g.0.4 ×10 means( 𝑜𝑓; 10) = 4.0; Or multiply the whole numbers 4 and 10, 10 and place the decimal point at one decimal place, since 0.4 has one decimal place E.g. 3 To multiply a decimal fraction (up to thousandths) by a whole number, first ignore the decimal point and multiply the whole numbers, check the number of decimal places and place the decimal point', 310),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.5.1', 'Demonstrate understanding of percentage of a given number', 'B5.1.5.1.1', 'Determine the percentage of a given quantity (limit to 2-digit whole number) and vice versa 2 1', 'E.g. 1 Review multiplying a fraction by a whole number. e.g. ×10 means shade 2×( 𝑜𝑓; 10) ; 5 5 i.e. 2×(2) = 4; E.g. 2 To multiply a percent fraction by a whole number, change the percentage to common fraction and multiply 40 and simplify e.g.40% ×10 means ( 𝑜𝑓; 10) = 4; 100 E.g. 3 Ask learners to find given percentage of given quantities; e.g. What is 20% of 45?', 320),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.5.1', 'Demonstrate understanding of percentage of a given number', 'B5.1.5.1.2', 'Determine the benchmark percentages from their common fractions and use these to estimate percentages of quantities', 'E.g. 1 Use pictorial representations and chart to display common or benchmarks percentages and ask pupils to determine these from their equivalent common fractions. E.g. 2 Give learners practice through drills and games to learn the equivalences of the benchmark fractions E.g. 3 Ask pupils to use the benchmarks for estimating percentages of given quantities. E.g. for “what is 60% of 45?” using the nearest benchmark fraction (i.e. 50%) the learner will know the expected result is close to 30;the learner can use benchmark fractions to determine the result mentally by finding which can 1 1 easily multiply 45, and in this case to give; 9. Since is 20%, then the 5 5 60% required will be 3 times 9 which is; 27. E.g. . Ask pupils to use the benchmarks for estimating and determining the results of finding percentages of given quantities and then verify by working; that is, changing the percentage to common fraction and multiplying by the quantity', 330),
('Basic 5', 'Mathematics', 'maths', 'Number', 'Number: Fractions', 'B5.1.5.1', 'Demonstrate understanding of percentage of a given number', 'B5.1.5.1.3', 'Identify and describe percent from real-life contexts and solve problems using percent', 'E.g. 1 Discuss the contexts below in which fractions are used in real life and provide materials for pupils to act them out  In shops – discounts, reduction to clear – 50%, etc.  In exams expressing marks as percentages  Phone battery power used etc. E.g. 2 Drawing circle graphs that represent that represent various percentages of halves, fourths and eighths. The graph shows the ages of pupils in Primary; 4. If there are 40 pupils in the class, ask questions for pupils to interpret the graph', 340),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.1', 'Extend a given pattern with and without concrete materials, and explain how each element differs from the preceding one', 'E.g. 1 Skip count in multiples of 20, 50, 500, etc. is one way to introduce patterns. E.g. 2 Provide students with a thousand number chart or number line with missing numbers and help use the strategy of skip counting to find missing numbers', 350),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.2', 'Describe, orally or in writing, a given pattern, using mathematical language, such as one more, one less, five more, one more than or less than twice, etc', 'E.g. 1 Lines are drawn to intersect two lines in each diagram and the number of points of intersection are counted to form a sequence. Ask learners to tabulate your results for the next four terms in the sequence and complete the table Find the rule for lines Number of lines 1 2 3 4 5 6 ∙ ∙ Intersections 2 4 Guide learners to describe the relationship as “intersection is one less number of lines” E.g. 2 Consider a design on the wall is being made using square tiles of size 10cm by 10cm Ask learners to find the number of joints made by the tiles if one, two, three, four, etc. of the squares tiles are used, and use it to complete the following table and describe the relationships. Number of tiles 1 2 3 4 5 Number of joints 0 1', 360),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.3', 'Predict subsequent elements in a given pattern', 'E.g. 1 Ask students to respond to find the next two terms in a pattern and state the rule for the pattern. E.g. 2 Ask learners to complete the table below for the number of match sticks used in this geometric pattern. Guide learners to describe the relationship. E.g. 3 Ask learners to write questions based on number or geometric patterns for their friends to find answers to; e.g. how many match sticks will be used for the 9th geometric pattern? Number of triangles 1 2 3 4 5 n Number of match sticks 3 6', 370),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.4', 'Represent a given pattern visually to verify predictions', 'E.g. 1 Ask learners to examine the pattern in the table below which shows the number of match sticks used in making a pattern of triangles. Pattern Number (sticks in side) 1 2 3 4 5 6 7 8 9 Number of match sticks 3 9 18 Ask learners to use match sticks to make the patterns of triangles and complete the table. Guide learners to describe the relationship E.g. 2 Ask learners to examine the pattern in the table below which shows the number of match sticks used in making a pattern of squares Ask learners to use match sticks to make the patterns of triangles and complete the table. Guide learners to describe the relationship Pattern Number (sticks in side) 1 2 3 4 5 6 7 8 9 Number of Pattern 1 triangles 1 4 9 E.g. 3 Ask learners to write questions based on number or geometric patterns for their friends to find answers to; e.g. how many match sticks will be used for the 9th pattern of squares? How many match sticks will be used for the 8th pattern of squares?', 380),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.5', 'Solve a given problem by using a pattern rule to determine subsequent elements', 'E.g.; 1. Ask learners to describe the pattern rule for each example and determine the next three elements of each: (i) 1, 10, 7, 70, 67, 670, ... (ii) 10, 12, 16, 22, 30 ... (iii) 50, 48, 47, 45, 44 ... E.g.; 2. Ask learners to describe the pattern rule for each of the patterns and determine the next three elements: (i) .25, .5, .75, ___, ___, ___, (ii) 2.50, 5, 7.50, ___, ___, ___, (iii) 64, 32, 16, , ___, ___, ___, (iv) 900, 450, 225, , ___, ___, ___,', 390),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.6', 'Determine and explain why a given number is or is not the next element in a pattern', 'E.g. 1 Ask students to respond to the following prompt: Shika filled bags with marbles. She placed two marbles in the first bag, four marbles in the second bag, six marbles in the third bag, eight marbles in the fourth bag and twelve in the fifth bag. Her friend Ayerko noticed an error in the pattern. Can you identify and describe the error? Bags 1 2 3 4 5 6 7 Marbles 2 4', 400),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.7', 'Write a rule in words and in algebra to represent a given pattern', 'E.g.; 1. E.g.; 1. Ask learners to state the rules in words and in algebra to represent a given increasing linear patterns.', 410),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B5.2.1.1', 'Determine the pattern rule to make predictions about subsequent elements', 'B5.2.1.1.8', 'Describe the relationship in a given table or chart, using a mathematical expression E.g.1 This table shows the pattern of cost of boxed lunches for students on a field trip. Ask learners to: (i) explain the pattern of how the cost of lunches changes as more students go on the trip; (ii) use the pattern to determine how many students went on the trip if the cost of lunches is GHC90. Number of students 1 2 3 4 5 ? Cost of lunch in cedis 3 6 9 12 15 90', 'E.g. Ask learners to write questions based on the pattern for their friends to find answers.', 420),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Algebraic Expressions', 'B5.2.2.1', 'Demonstrate understanding of algebraic expressions', 'B5.2.2.1.1', 'Demonstrate understanding of algebraic expressions as mathematical phrases that can contain letters which represent ordinary numbers and operators (like add, subtract, multiply, and divide)', 'E.g.; 1. Write algebraic expressions for word problems:; 1) Sum of 8 and s; 2) 8 times the sum of c and 7; 3) Take away 4 from m; 4) Subtract 4 from 7 times g E.g.; 2. Write algebraic expressions for the perimeter of the following shapes', 430),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Variables and Equations', 'B5.2.3.1', 'Solve problems involving single- variable, one-step equations with whole number coefficients', 'B5.2.3.1.1', 'Express a given problem as an equation where the unknown is represented by a letter to variable', 'E.g.1. Ask learners solve word problems; e.g.. i. The cost of two pens is twenty ¢15. If one costs ɇ5.50, what is the cost the other pen? ii. The product of two numbers is 120. If one of the numbers is 24, what is the other number? E.g.2. Ask learners to read Ama’s problem below, complete the table and solve the problem Days (d) Days 1 2 3 4 5 Height (h) Height 5cm 7cm Ama is tracking the progress of her plant’s growth. Today the plant is 5cm tall. The plant grows 2cm a day (i) Write a mathematical sentence that represents the height of the plant after d days; (ii) What will the height of the plant be after 20 days? (iii) How many days will the height take to reach 75cm?', 440),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Variables and Equations', 'B5.2.3.1', 'Solve problems involving single- variable, one-step equations with whole number coefficients', 'B5.2.3.1.2', 'Identify the unknown in a problem; represent the problem with an equation; and solve the problem concretely, pictorially or symbolically. E.g.1 Learners use concrete materials, such as blocks or counters and the balance scales, to find the value of p in the following equations. If necessary, model the use of guess and test as one strategy. By observing patterns in their results, students become more systematic in the guesses they make', '1. 3 + p =11; 5. p + 5 = 17; 2. 14 - p = 8; 6. 24 = p + 9; 3. p - 9 = 16; 7. 25 = 35 - p; 4. 3p = 12', 450),
('Basic 5', 'Mathematics', 'maths', 'Algebra', 'Variables and Equations', 'B5.2.3.1', 'Solve problems involving single- variable, one-step equations with whole number coefficients', 'B5.2.3.1.3', 'Create a problem for a given equation E.g.1 Ask students to describe two different stories that the equation 5 + k = 9 could represent E.g.2', 'Ask learners to solve puzzle in the figure, by solving the equations in each line', 460),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Perimeter, Area, Capacity/Volume and Angle', 'B5.3.1.1', 'Identify and sort quadrilaterals, including rectangles, squares, trapezoids, parallelograms, and rhombuses, according to their attributes', 'B5.3.1.1.1', 'Demonstrate an understanding of the properties (', 'e.g. sides, angles, and diagonals) of squares and rectangles E.g. 1 Give learners photocopied worksheets with shapes to identify squares and rectangles and give reasons. (Or Draw on the chalk board)', 470),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Perimeter, Area, Capacity/Volume and Angle', 'B5.3.1.1', 'Identify and sort quadrilaterals, including rectangles, squares, trapezoids, parallelograms, and rhombuses, according to their attributes', 'B5.3.1.1.2', 'Use paper folding with cut-out squares and rectangles to investigate sides, angles, and diagonals properties', 'E.g. 1 Give learners foldable cut-out 2D squares and rectangles to investigate the properties in terms of sides, angles, and diagonals and complete the table Properties Rectangle Square Sides All sides are congruent No Yes Opposite sides are congruent Opposite sides are parallel Angle Opposite angles are congruent All angles are right angles Diagonals Diagonals bisect each other Diagonals are congruent Diagonals meet at right angles', 480),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement – Perimeter, Area, Capacity/Volume and Angle', 'B5.3.1.1', 'Identify and sort quadrilaterals, including rectangles, squares, trapezoids, parallelograms, and rhombuses, according to their attributes', 'B5.3.1.1.3', 'Prove that a polygon is regular by measuring the sides and angles or by folding and superimposing', 'E.g. 1 Give learners foldable cut-out 2D quadrilaterals - rectangles, squares, trapezoids, parallelograms, and rhombuses - to investigate the properties in terms of sides, angles, and diagonals and complete the table Properties Rectangle Square rhombuses trapezoids parallelograms Sides All sides are congruent No Yes Opposite sides are congruent Opposite sides are parallel Angle Opposite angles are congruent All angles are right angles Diagonals Diagonals bisect each other Diagonals are congruent Diagonals meet at right angles', 490),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.2.1', 'Estimate and measure perimeter and surface area of 2-D shapes using centimetre and metre', 'B5.3.2.1.1', 'Estimate perimeter using referents for centimetre and metre, and calculate the actual perimeter and compare', 'E.g. 1 Using pupils’ referents for centimetre (hand span and thumb width) or metre (two strides or pace steps) estimate and calculate perimeter of any object in the classroom (e.g. exercise book, floor tiles, math set, teacher’s table, classroom floor, etc.) then measure with a ruler of tape and calculate the actual perimeter and compare the answers.', 500),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.2.1', 'Estimate and measure perimeter and surface area of 2-D shapes using centimetre and metre', 'B5.3.2.1.2', 'Calculate perimeter of given shapes in centimetres and metres', 'E.g. 1 Give learners 2D shapes with given dimensions to find the perimeter by adding the distance around the shapes', 510),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.2.1', 'Estimate and measure perimeter and surface area of 2-D shapes using centimetre and metre', 'B5.3.2.1.3', 'Calculate surface area of given shapes in centimetres and metres', 'E.g. 1 Give learners compound 2D shapes that can be spilt to many rectangles with given dimensions to find the surface area by adding areas of the various rectangles', 520),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.2.2', 'Demonstrate an understanding of volume of common 3D shapes. CONT’D', 'B5.3.2.2.1', 'i.e. 1000litres is 1m3] Note: the volume is the actual amount of something which covers a definite space', 'E.g. 1 Show learners an object which is a cubic centimetre (or 1 cm3) and another object which is a cubic metre (or 1 m3) E.g. 2 Let learners explore the classroom and compound to find that can be used as referents for the cubic centimetre (1cm3) and cubic metre (1m3). Example of 1m3is polytank; and 1cm3is cube sugar. E.g. 3 Ask learners identify containers in the classroom and compound that can be measured using cubic centimetre (cm3) and cubic metre (m3) E.g. 4 Ask learners to explore and state the relationship between 1cm3 and 1m3; that is, a cubic is the volume of a cube with measurements 1cm×1cm×1cm, and is equal to1/1,000,000of a cubic meter,1/1,000 1000 of this10×10×10 of a litre (i.e. 1m3=100cm×100cm×10cm =1,000,000cm3). cubes is 1m3', 530),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.2.2', 'Demonstrate an understanding of volume of common 3D shapes. CONT’D', 'B5.3.2.2.3', 'Determine different sizes of boxes that have the same volume', 'E.g. 1 Given 12 centimetre cubes, ask learners to find the different dimensions of boxes that can take the cubes. For 12 cubes the boxes can be of dimension 1cm×1cm× 12cm or 2cm×2cm×6cm. Can we find any more drawings. E.g. 2 Ask learners to investigate with 20, 24, 30 and 48 centimetre cubes and draw all possible boxes', 540),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.3.2', 'Demonstrate an understanding of volume of common 3D shapes CONT’D', 'B5.3.3.2.2', 'Determine the volume of boxes by finding how many cubes of sizes 1cm3 each contains', 'E.g. 1 Ask learners to determine the volume of different sizes of boxes by investigating how many cubes of sizes 1cm3 can fill the containers. i.e. for box A, the base can take 2 by 7 1cm3, and to fill it this arrangement will done 3 times, hence Volume of A is base area × height = 2×7×3=42cm3 E.g. 2 Ask learners to determine the volume of the boxes B, C, D and E E.g. 3 Guide learners to deduce the rule for volume of a box, and use is to calculate volumes of given boxes – F, G and H. That is, if the base area is 𝑙 ×𝑤 and the height is , then the. Volume of box is given by 𝑙 ×𝑤 ×ℎ', 550),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.3.2', 'Demonstrate an understanding of volume of common 3D shapes. CONT’D', 'B5.3.3.2.4', 'Demonstrate an understanding of capacity by describing the relationship between capacity and volume as well as litre and 10cm3', 'E.g. 1 Give learners a litre container and a 10cm×10cm×10cm container (i.e. a 1000cm3container. Ask them to fill one with water and empty it into the other; and ask them to explore and state the relationship between 1cm3 and 1m3i.e. 10cm×10cm×10cm =1000cm3 = 1litre. [see', 560),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.3.3', 'Demonstrate an understanding of angles', 'B5.3.3.3.1', 'Identify examples of angles in the environment that are equal to, less than or larger than, a right angle', 'E.g. 1 Review the definition of angles: angles as the region formed in a plane when two lines meet or cross, they form an Angle. And ask learners to identified angles in the classroom and compound. E.g. opening laptop, door, window, pair of scissors, pavement floor, etc. E.g. 2 Guide learners to see right angles and fold right angles from paper. Ask learners to identify examples of angles in the classroom and compound that are equal to, less than or larger than, a right angle', 570),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement', 'B5.3.3.3', 'Demonstrate an understanding of angles', 'B5.3.3.3.2', 'Measure given angles with a protractor and classify them according to their measured sizes', '– right, acute, obtuse and reflex E.g. 1 Review with learners how to use the protractor to measure angles E.g. 2 Give learners photocopied worksheets with protractor in position measuring angles; ask them to read the angles or place their protractors on it and read it E.g. 4 Give learners photocopied worksheets with several angles to measure and sort into those which are – right, acute obtuse angles. E.g. 5 Ask learners to draw various angles such as 30o, 45o,60o, 75o, 90o, 120o, 150o,270o, etc.', 580),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Geometric Reasoning', 'B5.3.4.1', 'Describe the position of objects in space using the cardinal points', 'B5.3.4.1.1', 'Tell the position and motion of objects in space using the cardinal points north, south, east and west', 'E.g.; 1. Pupils describe the position and motion of objects from one point to another using the 4 main cardinal points: e.g. The point P is to the west of point T but to the north of the A E.g.; 2. Pupils describe the position of places in a grid from a given location. E.g. from Kofi’s house - the school is East of Kofi’s house; the hospital is North of Kofi’s house E.g.; 3. Ask learners to give directions from Kofi’s house the various locations. E.g. Move 2 squares to the east and 2 squares to the north to get to the church', 590),
('Basic 5', 'Mathematics', 'maths', 'Geometry and Measurement', 'Geometric Reasoning', 'B5.3.4.2', 'Perform a single transformation (i.e. reflection) on a 2D shape', 'B5.3.4.2.2', 'Identify images of a single transformation (i.e. reflection) of a 2D shapes in a plane', 'E.g.; 1. Ask learners to identify images of reflections of given 2D shapes in a given plane. Ask learners to study the shapes and the mirror line and state which are objects and their images in the given four mirror lines. Shape E is the image of Shape B in mirror line 2 or the line 𝑥 = 0; shape A is a reflection of shape E in the line 𝑦 = 𝑥.', 600),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B5.4.1.1', 'Differentiate between first-hand and second- hand data', 'B5.4.1.1.1', 'Explain the difference between first-hand and second-hand data', 'E.g.; 1. Explain first-hand data as data that you collect on your own; and second-hand data is data that has been collected and organized by somebody else. E.g.; 2. Mrs. Acquaye’s class studied the weather. The learners measured the rainfall for 5 days (Monday to Friday). For her class these results are first-hand data. But for another class these results are second-hand data.', 610),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B5.4.1.1', 'Differentiate between first-hand and second- hand data', 'B5.4.1.1.2', 'Find examples of second-hand data in print and electronic media, such as newspapers, magazines, and the internet', 'E.g.; 1. Look for examples of second-hand data in the newspaper or website; You can find data on league table, price list, sales, rainfall, etc. E.g.; 2. Ask learners to study the second-hand data on the league table and write questions for their friends to read and interpret the data. E.g. Which team has not lost in a match? Which team has won only one match?; E.g. 3. Ask learners to study the second-hand data on suggested number of 30 minutes periods that Ghanaian primary school children learn certain subjects every week. Ask them to write questions for their friends to read and interpret the data.', 620),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B5.4.1.2', 'Construct and interpret double bar graphs to draw conclusions', 'B5.4.1.2.1', 'Draw double bar graphs, complete with title, labelled axes, key or legend, to represent data collected (up to 3 pairs of categories of data and use it to solve problems', 'E.g.; 1. Give students data presented in a table on rainfall in mm for two towns to draw a double bar graph complete with title, labelled axes, key January February March April May June Kumasi 5 10 15 20 50 45 Oda 3 10 13 25 40 50', 630),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Data Collection, Organisation, Presentation, Interpretation and Analysis', 'B5.4.1.2', 'Construct and interpret double bar graphs to draw conclusions', 'B5.4.1.2.2', 'Identify examples of double bar graphs used in a variety of print and electronic media, such as newspapers, magazines, and the internet', 'E.g.; 1. Provide opportunities for learners to access, read and interpret examples of double bar graphs used in a variety of print and electronic media, such as newspapers, magazines and the internet', 640),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Chance (Probability)', 'B5.4.2.1', 'Describe the likelihood of a single outcome occurring using words such as impossible, possible, and certain', 'B5.4.2.1.1', 'Classify the likelihood of a single outcome occurring in a probability experiment as impossible, possible, or certain', 'E.g. In a Ludo competition with a die, the event of “obtaining the number 1” is possible; the event of “obtaining the number 7” is impossible; the event of “obtaining the number 1 or 2 or 3 or 4 or 5 or 6” is certain.', 650),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Chance (Probability)', 'B5.4.2.1', 'Describe the likelihood of a single outcome occurring using words such as impossible, possible, and certain', 'B5.4.2.1.2', 'Design and conduct an experiment in which the likelihood of a single outcome occurring is impossible, possible (likely or unlikely), certain', 'E.g. In a bag containing 10 red, 4 green and 1 pink bottle tops, let a learner pick one bottle top from the bag.; 1. Picking a black bottle top is impossible; 2. Picking a red bottle top is possible (likely); 3. Picking a pink bottle top is possible (unlikely); 4. Picking a red or green or pink bottle top is certain. Explain each of the four outcomes', 660),
('Basic 5', 'Mathematics', 'maths', 'Data', 'Chance (Probability)', 'B5.4.2.1', 'Describe the likelihood of a single outcome occurring using words such as impossible, possible, and certain', 'B5.4.2.1.3', 'Conduct a given probability experiment a number of times, recording the outcomes, and explaining the results', 'E.g. Ask 5 learners of their expectations/predictions about the outcome of tossing a coin three times. Teacher tosses a coin three times and records the outcome. (e.g. head, head, tail) Does the outcome match their expectation? Either way the teacher should explain. In pairs, learners should repeat the experiment several times, record the outcomes and compare the number of heads turning up', 670),
('Basic 5', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B5.1.1.1', 'Appreciate the nature of God as the Creator', 'B5.1.1.1.1', 'Explain how special each individual is', 'Through various activities such as working in pairs or in groups, let learners discuss how each person is unique and different from one another: some are short, tall, intelligent, fair in complexion, black in complexion, serious, etc.; Lead learners to demonstrate the uniqueness of each individual, using themselves.; Put learners into groups according to: height, colour, mass, intelligence, etc.; Let learners put in writing how different they are from each other.', 10),
('Basic 5', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B5.1.1.1', 'Appreciate the nature of God as the Creator', 'B5.1.1.1.2', 'State the qualities of God that humankind should demonstrate', 'Let learners mention qualities of God that humankind should demonstrate: love, patience, mercy, kindness, forgiveness, honesty, accountability etc.; Let learners discuss among those qualities of God they should possess to make them God’s children.; Let learners, in pairs or in groups, discuss how they can use their God-given unique qualities: - Serve God and humankind, - Protect and preserve the environment, - Live together in harmony, - Contribute to development, etc.; Let learners present their work for appreciation and discussion in class.', 20),
('Basic 5', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B5.1.1.1', 'Appreciate the nature of God as the Creator', 'B5.1.1.1.3', 'Mention why individuals should maintain their God-given gifts of form and colour', 'Let learners give reasons why they should maintain their God-given form and colour: God has a purpose for creating everybody as they are. No-one creates himself or herself.Our bodies serve as the Temple of God.; Let learners discuss possible purposes for which each one is created in a unique form.; Use pictures or video clips (where possible) to demonstrate the effects of destroying our bodies.; Put learners in groups to discuss how to maintain their God-given form and colour and not to deform their bodies.We should be proud of how we were created.We should avoid bleaching the skin.', 30),
('Basic 5', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Environment', 'B5.1.2.1', 'Explain how to care for the environment', 'B5.1.2.1.1', 'Discuss the effects of human activities on the environment', 'Guide learners to talk about the human activities in the environment.; Show pictures and video clips on human activities that destroy the environment: illegal mining (galamsey), indiscriminate cutting down of trees (deforestation), pollution of water bodies, air pollution, etc.; Let learners write the effects of human activities on the environment: climate change – heat, floods, rain storms, less rainfall, famine, drought, etc.', 40),
('Basic 5', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Environment', 'B5.1.2.1', 'Explain how to care for the environment', 'B5.1.2.1.2', 'Demonstrate ways to care for the environment', 'Through questions and answers, learners explain what they think a clean environment should be.; Using Think-Pair-Share, learners talk about ways of caring for the environment through: tree planting, proper disposal of wastes, legal mining, clean-up exercises, avoiding environmental pollution, etc.; Let learners organise and do clean-up exercises in the school environment.; Guide learners in groups to do a project on: clearing a rubbish dump, planting trees, checking erosion, clearing choked gutters, etc.; Let learners discuss and write down the importance of caring for the environment: the importance may include: it helps to improve climatic conditions such as adequate rainfall, balanced temperature on earth, etc.; Let learners present their work in class for appreciation and discussion.', 50),
('Basic 5', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship in the Three Major Religions in Ghana', 'B5.2.1.1', 'Appreciate the importance of prayer, worship and other acts of worship', 'B5.2.1.1.1', 'Discuss the moral importance of worship', 'Help learners (in groups) to explain modes of worship: charity, prayer, song ministration, evangelism, etc.; Let learners give reasons why we worship: humankind is under the authority of the Creator, we demonstrate that we depend on God for survival, etc.; Through questions and answers, assist learners to talk about the importance of worship: to get blessings from God, to get closer to God, etc.; Have children show how they pray.', 60),
('Basic 5', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship in the Three Major Religions in Ghana', 'B5.2.1.1', 'Appreciate the importance of prayer, worship and other acts of worship', 'B5.2.1.1.2', 'Explain the moral significance of religious songs and recitations', 'Let learners identify religious songs of the three major religions in Ghana.; Let learners listen to cassette (CD) player of religious songs in the three major religions and indicate how they can apply the theme in their daily lives.; Put learners into religious groups to take turns to perform various religious music and dance.; Let learners, in groups, discuss the importance of religious songs in worship: they encourage worship; they make worship lively, they tell us about the nature and attributes of God in melodious and harmonious manner, etc.; Let Learners compose simple religious songs and poems.', 70),
('Basic 5', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Festivals in the Three Major Religions', 'B5.2.2.1', 'Explain the Significance of Religious Festivals', 'B5.2.2.1.1', 'Identify the moral significance of sacred passages and oral traditions in the three main religions', 'Give selected passages and or oral traditions for learners to study e.g. the Ten Commandments - (Exodus 20,), Al- Fãtihah, folktales, etc. and show how they can apply them in their daily lives.; Guide learners to identify sacred passages and oral traditions in the three main religions in Ghana.; Let learners isolate moral elements that can be found in the passages and narratives: this reinforces trust in God, helps to control stress, gives hope, guides our behaviours, etc.', 80),
('Basic 5', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Ministry of the Leaders of the Three Major Religions in Ghana', 'B5.3.4.1', 'Show an understanding of the ministry of each of the major religious leaders', 'B5.3.4.1.1', 'Describe the key events in the ministry of the leaders of the three religions', 'Guide learners to describe the key events associated with the ministry of the leaders of the three main religions: - The Lord Jesus Christ- Baptism, temptation, call of the disciples, teaching, etc. - The Holy Prophet Muhammad (S.A.W.) - call, triumphant entry to Makkah , etc. - Traditional Leader- training, teaching, etc.; In groups, let learners role-play some aspects of the ministry of: - The Lord Jesus Christ, - The Holy Prophet Muhammad and - A Traditional Religious Leader.', 90),
('Basic 5', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'Ministry of the Leaders of the Three Major Religions in Ghana', 'B5.3.4.1', 'Show an understanding of the ministry of each of the major religious leaders', 'B5.3.4.1.2', 'Outline the moral lessons from the ministry of the various leaders', 'Put learners in groups to identify the significant roles by the religious leaders in their ministries: obedience; commitment; patience, leadership, sacrifice etc.; In groups, let learners dramatise portions of the scripture that depict moral lessons, e.g. submissiveness, humility, loyalty, etc.', 100),
('Basic 5', 'Religious & Moral Education', 'rme', 'The Family and Commitment', 'The Family and the Community', 'B5.4.1.1', 'Explain Family Commitment', 'B5.4.1.1.1', 'Explain the need to be a committed member of the family', 'Have learners mention behaviours and attitudes needed to be a committed family member: - Initiates activities for family members eg. Periodic get- together - Supports common family projects eg. Taking care of needy person in the family - Visitation (taking time off to visit elders, parents, etc.) - Accepting responsibility (support family members who lag behind in performing their assigned duties) - Helping to instil discipline among younger family members, etc.; Learners discuss the need for being a committed family member: - to promote unity, - to gain respect, - to bring unity and peace in the family, - to strengthen the family support system, - to be considered a trustworthy person, etc.; In groups, let learners role-play a family sketch centred on commitment. The sketch should have commitment as its theme.', 110),
('Basic 5', 'Religious & Moral Education', 'rme', 'The Family and Commitment', 'The Family and the Community', 'B5.4.1.1', 'Explain Family Commitment', 'B5.4.1.1.2', 'Demonstrate things to do to show commitment as members of the family', 'Guide learners to sketch a demonstration on the following: - taking part in family programmes and activities, - contributing to and attending weddings, funerals, naming ceremonies, etc.; In groups, let learners discuss things they have to do to show commitment to their family.', 120),
('Basic 5', 'Religious & Moral Education', 'rme', 'The Family, Authority and Obedience', 'Authority and Obedience', 'B5.5.1.1', 'Appreciate the need to obey and submit to authority', 'B5.5.1.1.1', 'Recognise parents as sources of discipline and character formation', 'Through questions and answers, let learners mention how they are disciplined by their parents and other elders at home: - scolding, - reprimanding, - deprivation of gifts and other interests, - prayer and worship at home, - parents act as role models to the children/learners, etc.; Guide learners to talk about the benefits they get from their parents because of their obedience to them.; In groups, let learners demonstrate how their parents discipline them at home.', 130),
('Basic 5', 'Religious & Moral Education', 'rme', 'The Family, Authority and Obedience', 'Authority and Obedience', 'B5.5.1.1', 'Appreciate the need to obey and submit to authority', 'B5.5.1.1.2', 'Explain the need to demonstrate responsible behaviour at home', 'Let learners identify ways by which they can be responsible: - be a good child to avoid punishment, - emulate parents and other family members, etc.; Let learners dramatise responsible behaviours as parents.; In groups, let learners write essays on how to become responsible adults.; Let learners present their works to the class for appreciation and discussion.', 140),
('Basic 5', 'Religious & Moral Education', 'rme', 'The Family, Authority and Obedience', 'Roles, Relationships in the Family and Character Formation', 'B5.5.2.1', 'Explain the contributions of a responsible family member', 'B5.5.2.1.1', 'Discuss the importance of being a responsible member of the family', 'Assist learners to explain a responsible person in the family.; Let learners describe attitudes and behaviours that show that a person is responsible.; Ask learners to describe a responsible family member: - show commitment in family taking activities, - obedience to elders of the family, - respect for family members, - accepting responsibility (performing assigned duties), - taking initiatives, - helping needy relatives, etc.; Guide learners to discuss the importance of being a responsible family member: - to promote unity, - to gain respect, - to be considered a reliable person, etc.; Let learners role-play activities of responsible family members.', 150),
('Basic 5', 'Science', 'science', 'Diversty of Matter', 'Living and Non-living Things', 'B5.1.1.1', 'Understand the physical features and life processes of living things and use this understanding to classify them', 'B5.1.1.1.1', 'Know the life processes of living things (growth, sensitivity to the environment, respiration and excretion)', 'Learners go outside the classroom to observe and identify various living and non-living things and discuss their observation.; Engage learners to watch pictures or animated videos of different living things (e.g. birds, insects, trees, reptiles, mammals, etc.) and comment on them.; Ask learners to identify the names of the living things from the video.; Use relevant examples and illustrations to demonstrate or explain sensitivity, respiration and excretion as life processes.; Learners go on a nature walk to observe sensitivity in the mimosa plant when touched.; Assist learners to understand growth by observing a seedling and a mature plant of the same kind.; Let learners breathe air in and out to demonstrate respiration. NB: Plants show movement within their parts and animals move from place to place. Project: Learners plant a seed and observe its growth pattern.', 10),
('Basic 5', 'Science', 'science', 'Diversty of Matter', 'Living and Non-living Things', 'B5.1.1.2', 'Demonstrate understanding of the differences between living things, non-living things, and things which have never been alive', 'B5.1.1.2.1', 'Compare the differences among things that are living, dead and things that have never been alive', 'Assemble living things (e.g. plants, insects, etc.), non-living things (e.g. firewood, pencils, paper, etc.) and things that have never lived (rocks, soil, water, etc.) for class activities. NB: Wear protectives when gathering specimen.; Learners observe and comment on the samples.; Learners, in an activity, classify the provided specimen as (1) Things that are alive (2) Once alive or (3) Never been alive. Learners are guided to compare the differences among things that are alive, once alive or never been alive.; Learners explain why they (learners) are classified as living things.', 20),
('Basic 5', 'Science', 'science', 'Diversty of Matter', 'Materials', 'B5.1.2.1', 'Recognise materials as important resources for providing human needs', 'B5.1.2.1.1', 'Classify everyday materials based on their properties (soft, hard, rough, smooth, opaque, transparent and bendable)', 'Learners are asked to collect and bring a variety of everyday materials from the home, school and community. Examples should include cotton wool, pieces of cloth, pieces of paper, cardboard, wood, plastics, polythene bags (coloured and transparent), soil samples, marbles (rough and smooth) chalk, crayon, pen and straw.; Learners are assisted to sort and group the materials based on texture (hard or soft), and size (big or small).; Demonstrate by assisting learners to group materials into those that we can see through (transparent) and those that we cannot see through (opaque).; Learners sort the materials into those that can bend and those that cannot bend.; Learners feel and draw materials that are hard, soft, smooth, etc.; Learners are tasked to display their drawings in class for discussion.; Learners are assisted to know that the properties of a given material enable it to be used for making certain products, e.g. clay is used for making pots because it can be moulded without breaking. raffia palm is used in basketry because it can bend easily.; Learners work in groups to classify different materials based on various similarities and differences. Project: Learners use different materials to create new items such as paper fans, toy cars, toy planes, cooking pans, hats and earthenware pots and bowls and exhibit their work.', 30),
('Basic 5', 'Science', 'science', 'Diversty of Matter', 'Materials', 'B5.1.2.2', 'Know that substances can exist in different physical states (solid, liquid, gas). Many substances can be changed from one state to another by heating or cooling', 'B5.1.2.2.1', 'Know that some changes are reversible, while others cannot be reversed', 'Provide substances such as candle wax, shea butter, water, paper and a source of heat.; In groups learners undertake the following activities (e.g. melting of candle wax, melting of ice, melting of shea butter, heating of water, crumpling of paper, melting of plastics, burning of paper, burning of wood, etc.).; Learners, in their groups, talk about their observations.; Assist learners to classify the activities as (1) lead to the formation of a new thing, (2) no new thing formed.; Assist learners to understand that changes where no new thing is formed are reversible, while changes where new things are formed are usually not reversible. NB: Hazardous chemicals and solutions should not be used.', 40),
('Basic 5', 'Science', 'science', 'Diversty of Matter', 'Materials', 'B5.1.2.3', 'Understand mixtures, the types, formation, uses and ways of separating them into their components', 'B5.1.2.3.1', 'Demonstrate formation and separation of mixtures (solid-liquid and liquid-liquid mixtures)', 'Display some solid and liquid substances for learners to observe, e.g. water, common salt, vinegar, sugar, sand, cooking oil and soft drinks.; Put learners in groups and ask them to add each of the substances to a separate quantity of water whilst stirring and observe what happens.; Learners describe the material combinations they have produced, i.e. as solid-liquid mixture, liquid-liquid mixture or a solution.; Learners find out the difference between a mixture of sand and water and a mixture of salt and water.; Learners also differentiate between the mixture of water and soft drink and the mixture of water and cooking oil.; Put learners into groups to demonstrate how to recover the salt from the salt solution.; Assist learners to separate different solid-liquid mixtures and liquid-liquid mixtures using separation methods such as filtration, evaporation, sieving and use of separating funnel. Project: Separation of solid- liquid mixture Learners separate a mixture of sand and water using appropriate materials. NB: Improvised separation equipment can be used to effectively separate various mixtures', 50),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.1', 'Recognise that some events in our environment occur recurrently', 'B5.2.1.1.1', 'Know how day and night are formed', 'Assemble materials such as polystyrene (plastic) balls, football, ice-cream stick, torch, pen and globe.; Learners are assisted to understand the terms, rotation and axis using a ball.; Explain how the motion of the earth causes day and night, with the aid of a globe.; Learners observe a demonstration of day and night, using appropriate materials, e.g. globe of the earth, blu tac, and lamp without shade and a dark room.; Learners, in their groups, demonstrate the formation of day and night using, polystyrene balls, ice-cream stick, torch, pen and globe.; Learners explain how day and night come about and draw diagrams to represent their work.', 60),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.2', 'Recognise the relationship between the earth and the sun B5.2.1.3 Show understanding of the roles of condensation, evaporation, transpiration and precipitation in the hydrological (water) cycle', 'B5.2.1.2.1', 'Describe the benefits of the sun to the earth', 'Put learners into groups to discuss the benefits the earth derives from the sun.; Learners, in their groups, present their findings. These may include the following; the sun provides warmth to the earth, light for plants to grow well, provides day and night cycles and energy.; Learners brainstorm on what will happen if there was no sun. Project: Importance of the sun to plant growth. Learners demonstrate the importance of sunlight to the growth of plants.', 70),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.3', 'Show understanding of the roles of condensation, evaporation, transpiration and precipitation in the hydrological (water) cycle CONT’D', 'B5.2.1.3.1', 'Demonstrate evaporation and condensation as important processes of the hydrological (water) cycle', 'Learners recite poems and rhymes involving the environment and water.; In groups, learners demonstrate evaporation and condensation, e.g. learners observe water drying off their wet hands (evaporation), covering water with a lid and observing water droplets on the lid after some time (evaporation & condensation).; Demonstrate evaporation by heating water until it boils (to be done by the teacher), then covering the boiling water with a sheet of transparent glass. Water vapour condenses on transparent glass (condensation).; Learners are assisted to understand how evaporation and condensation lead to the formation of rain.; Display pictures or simple diagrams of the water cycle showing evaporation and condensation.', 80),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.3', 'Show understanding of the roles of condensation, evaporation, transpiration and precipitation in the hydrological (water) cycle CONT’D', 'B5.2.1.3.2', 'Know how clouds are formed', 'Review composition of air with learners. This should include water vapour.; Ask learners the question: what are clouds? And assists learners to come out with this explanation: clouds consist of many tiny water droplets resulting from the condensation of water vapour into liquid water or ice.; Explain that upward vertical motion of air through the atmosphere cools water vapour to form clouds.; Learners demonstrate formation of clouds in a bottle.; Learners explain why clouds are not formed close to the surface of the ground.', 90),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.4', 'Demonstrate understanding of how carbon and nitrogen are cycled in nature', 'B5.2.1.4.1', 'Describe the uses of carbon dioxide and its effects on humans and life on earth', 'Learners mention the components of air (this should include carbon dioxide).; Learners are assisted in groups to answer the following questions: What is carbon dioxide? What is carbon dioxide used for? How does carbon dioxide get into the environment? Does carbon dioxide have adverse health effects? Does carbon dioxide have adverse effects on the environment?; Learners are assisted to identify some common uses of carbon dioxide such as for making fire extinguishers, fizzy drinks and for the process of food preparation in plants.', 100),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.5', 'Recognise water and air as important natural resources', 'B5.2.1.5.1', 'Identify human activities that make water unsuitable for human use', 'Begin by discussing the qualities of good drinking water and dangers of using unsafe water.; Learners, in groups, identify human activities that make water unsuitable for use, e.g. toxic waste disposal, sewage disposal, deforestation, mining, littering, pesticides, herbicides and fertilizer application and agricultural practices.; Learners brainstorm to come out with ways of preventing, minimizing and controlling water pollution. Project: Task learners to work in groups to create concept maps on the causes, control and prevention of water pollution.', 110),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.1.5', 'Recognise water and air as important natural resources', 'B5.2.1.5.2', 'Know how to make and keep air clean in our environment', 'Find out from learners what they understand by clean air and review things that pollute air (make air unclean) such as smoke from factories, car exhausts, bush burning and dust from construction sites and untarred roads.; Lead discussions to come out with the do’s and don’ts that will make or keep air clean in our homes and surrounding environment (planting of trees and grass and avoiding frequent and uncontrolled burning).; Learners are assigned to design a concept map on the causes, prevention and control of air pollution.; Learners draw and use a Future’s Wheel to trace the effects of water pollution on the environment.', 120),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.2.1', 'Demonstrate understanding of life cycle of a plant', 'B5.2.2.1.1', 'Relate structure of the parts of a plant (leaves, stem, root, flower) to the functions they perform', 'Discuss functions of parts of plants with learners.; Learners go on a nature walk to uproot young plants from school surroundings and bring them to class.; Learners, in groups, observe parts of the plants and relate them to the functions they perform, e.g. the thin and large surface area of leaves and the presence of green colouring matter enhance their work. The roots are for anchorage and absorption of nutrients from the soil. The stem supports the upper part of the plant; conduct water and minerals from the roots to the leaves; carry food from leaves to other parts of the plant.; Learners draw and colour a plant and label the parts.', 130),
('Basic 5', 'Science', 'science', 'Cycles', 'Earth Science', 'B5.2.2.1', 'Demonstrate understanding of life cycle of a plant', 'B5.2.2.1.2', 'Compare the differences in germination of bean and maize seeds', 'Learners are assisted to review the previous knowledge on seed germination.; Put learners in groups and provide them with dry beans and maize seeds.; Learners are assisted to plant the bean and maize seeds using transparent containers and soil.; Learners are guided to observe (1) the dry seed (2) when it absorbs water and swells (3) rapturing of the seed coat (4) sprouting of the root (5) sprouting of the stem and seed leaves (6) the elongation of the root and stem.; Learners find out where the seed leaves (cotyledons) remain, inside the soil or above the soil. NB: This activity will take some days.', 140),
('Basic 5', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B5.3.1.1', 'Recognise that different parts of the human body work interdependently to perform a specific function', 'B5.3.1.1.1', 'Know the parts of the respiratory system in humans', 'Introduce the lesson with songs on the parts of the body, e.g. head, shoulders, knees and toes.; Ask learners to breathe in and out for some time.; Relate the act of breathing to the respiratory system and guide learners to identify the organs of the system using charts or models.; Use role-play to guide learners to identify the functions of each part (different learners assume and role-play the functions of parts of the respiratory system, e.g. Ama is the lungs and Amina is the diaphragm).; Engage learners in an activity to design a breathing model using plastic bags, balloons, rubber bands and polythene bags.; Learners draw and label the respiratory system and state its function.; Learners are tasked to find out the diseases and lifestyles that affect the respiratory system adversely. Project: Assist learners to design an improvised breathing apparatus using plastics.', 150),
('Basic 5', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B5.3.2.1', 'Show understanding of the orderliness of the sun, planets and satellites in the solar system, as well as the important role of the sun in the existence of the solar system', 'B5.3.2.1.1', 'Identify the components of the solar system (sun, earth, moon, other planets, satellite)', 'Present learners with a chart, model or video depicting the solar system or draw the solar system on the board, using different colours to illustrate the different bodies.; Learners recite the poem, “I see the moon, and the moon sees me”.; Initiate a discussion on the importance of the sun to life on earth.; Explain to the learners that the earth orbits (moves around) the sun, leading to changes in seasons (it takes a year for the earth to move around the sun).; Learners are made to understand that heavenly bodies that move around the sun are called planets.; Learners observe the planet Venus, the brightest object in the sky before sunset or several hours after sunrise.; Learners are guided to role- play the sun and the planets in the solar system.; Share folktales about the sun and moon with learners.;  Learners should understand that all the planets move around the sun.  Learners to observe the planet Venus, the brightest object in the sky before sunset or several hours after sunrise. Project: Planning, designing and making a model of the Solar System Learners build a model of the solar system using suitable materials such as blu tack, clay, cardboard and wood. etc.', 160),
('Basic 5', 'Science', 'science', 'Systems', 'Ecosystem', 'B5.3.3.1', 'Show understanding of ecosystem, interdependency of organisms in an ecosystem and appreciate the interactions', 'B5.3.3.1.1', 'Know how various organisms are adapted to survive in their habitat', 'Begin the lesson with a matching activity using flashcards (write the names of different organisms on flashcards and a list of habitats on another set of flashcards for learners to match with).; Learners explain why a bird cannot live in water.; Learners discuss various habitats of animals and plants.; Brainstorm with learners to come out with the meaning of the term habitat.; Learners are asked to give examples of animals that live in water, land and trees.; Learners are assisted to discuss how various organisms adapt to their habitat, e.g. what enables fish to live in rivers, birds to live on trees? Project: Designing a habitat Learners plan, design and make a model of a habitat using card board, paper, blu tack and clay to show the homes of some animals.', 170),
('Basic 5', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B5.4.1.1', 'Demonstrate understanding of the concept of energy, its various forms and sources and the ways in which it can be transformed and conserved', 'B5.4.1.1.1', 'Explain how energy is transformed from one form to another', 'Explore learners’ previous knowledge on the forms of energy (e.g. Electrical, heat, light, sound).; Use some common devices (e.g. torch, radio, television, etc.) to demonstrate transformation of energy.; Learners discuss energy transformations that take place in the school, e.g. ringing of bell, beating of gong-gong, drumming, etc.; In groups, learner’s identity other forms of energy transformations in the school community and present their findings for discussion in the class.; Learners design a flow chart to explain how energy from the sun is transformed into energy for walking.', 180),
('Basic 5', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B5.4.1.1', 'Demonstrate understanding of the concept of energy, its various forms and sources and the ways in which it can be transformed and conserved', 'B5.4.1.1.2', 'Know how to use electricity efficiently in the home', 'Learners mention names of things that use electricity in the home.; Brainstorm with learners to come out with how they use the electrical gadgets.; Learners talk about what will happen if electrical gadgets are not switched off when not in use.; Elaborate on and link learners’ ideas with the issue of power outages and crisis which come as a result of the efficient use of electricity in our homes and industries.; Learners, in a think-pair-share activity, identify how they can use electricity efficiently in the home, community and school. e.g. ironing in bulk, putting off television sets and freezers when ironing, using energy-efficient bulbs and other electrical gadgets with higher energy efficient ratings: (more stars imply higher energy efficiency).', 190),
('Basic 5', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B5.4.1.2', 'Show understanding of the concept of heat energy in terms of its importance, effects, sources and transfer from one medium to another', 'B5.4.1.2.1', 'Show the relationship between heat and temperature', 'Review previous lesson on temperature with learners.; In a group discussion, learners find out what will happen when heat is applied to a substance or lost from a substance, e.g. when a substance is placed in the sun for a while or when a substance is put in a fridge.; Learners undertake an activity of placing objects such as metal plates, pieces of stone in the sun.; Learners initially touch the objects to feel their degree of warmness before they are put in the sun.; After 20 minutes, learners touch the objects again and feel the difference in temperature.; Learners should then place the stones or metals in a bowl of water and afterwards, touch again to determine whether they become hotter or colder.; Elaborate on learners’ ideas, emphasising heat as the factor that changes temperature.; Summarise lesson by explaining to learners that when heat is lost, temperature reduces, when heat is gained, temperature increases.', 200),
('Basic 5', 'Science', 'science', 'Forces and Energy', 'Electricity and Electronics', 'B5.4.2.1', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms', 'B5.4.2.1.1', 'Identify the components of an electric circuit and their functions', 'Begin by asking learners what comes into their minds when they hear the term, ‘electric circuit’; Learners watch pictures and videos of simple electrical circuits and how they work.; Learners, in groups, construct simple electric circuits using connecting wire, dry cells and a bulb/LED to light up the bulb.; Assist learners to identify the components and their uses.; Learners find out other materials that can be used in place of dry cells, connecting wires and bulb. Project: Learners build an LED lantern using the above circuit and plastic bottle.', 210),
('Basic 5', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B5.4.3.1', 'Know that movement is caused by applied forces due to the release of stored energy', 'B5.4.3.1.1', 'Explain the term, “friction”, its effects and applications', 'Review the previous lesson on forces with learners.; Learners recall some examples of forces and their effects/applications.; Learners explain why cars usually drive slowly on wet roads.; Task them to explain what happens when one accidentally step into an oil spill on the floor.; Ask learners these questions: What is friction? What does it do? How does it work?; Then discuss their prior knowledge of the topic.; Learners rub their palms together for several sections and talk about what they notice.; Explain to learners that the warmth they feel is caused by a force called friction and that friction is the force that opposes the movement of two surfaces against each other.; Some learners remove their shoes to show the shrunken heels/soles as an example of the effect of friction between the sole of the shoe and the ground which one walks on.; Emphasise the fact that it is because of the friction between the shoes and the ground that we do not fall whilst walking or running.; Explain to learners again that on a rainy day or on a smooth/polished surface, friction is reduced, which means the shoes of the one walking or the tyres of the car are not firmly gripped to the ground or the road because friction has reduced. Thus, this is what causes people to fall or slip on oily or wet surfaces. Project: Investigating the effect of friction Learners demonstrate the effect of friction by using a toy car on rough and smooth surfaces.', 220),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B5.5.1.1', 'Recognise the importance of personal hygiene', 'B5.5.1.1.1', 'Know why it is important to wash clothes regularly', 'Engage learners in groups to discuss among themselves what items are needed to wash their clothes and underwear.; Groups present their ideas to the whole class.; Present to learners, real items (soap, water, dirty clothes, etc.) needed to wash clothes and underwear and demonstrate how washing is done.; Learners demonstrate how washing is done (a learner from each group).; Engage learners to watch a video or pictures showing other methods of washing clothes and underwear, apart from the hands.; In pairs, learners share ideas on what will happen if they don’t wash their clothes and underwear regularly.; Guide learners to design personal roster for washing their clothes, indicating the days and times which they will use to wash their dirty clothes.', 230),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B5.5.1.2', 'Identify, discuss and appreciate the natural and human features of the environment and the need to keep the environment clean', 'B5.5.1.2.1', 'Know how to keep washrooms clean', 'Learners watch pictures and videos on how to keep washrooms clean.; Engage them in a discussion on how to keep the lavatory clean.; Emphasise such key points as: flushing immediately after use, urinating directly in the toilet bowl, keeping used tissues in waste containers rather than throwing them on the floor, regularly removing used tissues and burning them.; Learners investigate the risks associated with the use of dirty washrooms.; Evaluate learners by asking them to design a poster to be pasted in their school’s washroom.', 240),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B5.5.1.2', 'Identify, discuss and appreciate the natural and human features of the environment and the need to keep the environment clean', 'B5.5.1.2.2', 'Demonstrate how to clean the environment regularly', 'Assemble various items for cleaning the environment.; Begin the lesson with a song on cleanliness.; Take the learners on a trip to observe tidy and untidy parts of the nearby community or show different pictures depicting clean and unclean environments.; Engage learners to discuss how to make the unclean environments as clean as those that are clean.; Learners discuss some materials that are used for cleaning the home, the school and the community.; Demonstrate to learners the correct way of using the cleaning tools, e.g. brooms, rags, ceiling brush, dustpans and dustbins.; Learners are assisted to know the need to keep the environment clean.; Engage learners to use local cleaning tools to clean the classroom and the school environment. Project: Learners design posters to create awareness on the need to keep the school, home and Community clean and exhibit their work in the school. NB: Teachers are encouraged to form an environmental awareness club in the class after this lesson.', 250),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B5.5.2.1', 'Know common diseases of humans; causes, symptoms, effects and prevention', 'B5.5.2.1.1', 'Explain the causes, symptoms and control of chicken pox', 'Learners watch pictures, videos or charts on causes, symptoms and control of chicken pox or invite a health personnel or School Health Education Programme (SHEP) coordinator to give a talk on chicken pox.; In pairs, learners answer the following questions based on the pictures and video: (1) What causes chicken pox? (2) What are the symptoms of chicken pox? (3) What should be done if someone has chicken pox? (4) What are the ways of preventing the spread of chicken pox? Project: Learners develop a concept map to trace the causes, symptoms and prevention of chicken pox.', 260),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B5.5.2.1', 'Know common diseases of humans; causes, symptoms, effects and prevention', 'B5.5.2.1.2', 'Identify causes, symptoms and prevention of cholera', 'Learners watch pictures and videos or images showing the causes, symptoms and prevention of cholera.; Invite a local health officer or SHEP coordinator to give a presentation on cholera to the learners.; Engage learners, in groups, to discuss the causes of cholera, using everyday scenarios, e.g. eating contaminated food and living in a dirty environment.; Learners are provided one large cardboard for all the groups to write different ideas on the causes, prevention and symptoms of cholera.; Learners display the cardboard in the classroom.', 270),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Science and Industry', 'B5.5.3.1', 'Recognise the impact of science and technology in society', 'B5.5.3.1.1', 'Identify the raw materials used in some local industries (kenkey production, gari production, ceramic and pottery production)', 'Take learners to a local gari, kenkey, shea butter, cooking oil, blacksmith, basketry, carpentry or pottery production site or show videos of such ventures.; Learners observe critically and identify the raw materials used in the various industries.; Engage the learners in a matching activity to match some local products with their raw materials. Project: Designing an Industry. Learners plan and design a factory in their locality, showing the raw materials they use and the finished products.', 280),
('Basic 5', 'Science', 'science', 'Humans and the Environment', 'Climate Change', 'B5.5.4.1', 'Know that climate change is one of the most important environmental issues facing the world today', 'B5.5.4.1.1', 'Identify the impact of deforestation on climate change', 'Put learners into groups and let them discuss the importance of trees in the environment.; Take them on a trip around the school environs and help them to appreciate the importance of trees such as provision of shade, food, fresh air, production of rain, etc.; Learners brainstorm on what will happen if people continuously cut down trees.; Engage each group to present their ideas to the whole class and re-shape their ideas by writing all key points on tree-felling and its impact to the environment as well as its long-term effect on the climate.; Learners brainstorm on what measures to take to stop people from tree- cutting.; Learners are assisted to plant trees in their school environment and at strategic locations within the community.; Learners are supervised to take good care of the trees they plant.', 290);
